import {avatarProfile} from './avatar-profile.js';
const vec=v=>Array.isArray(v)&&v.length===3&&v.every(n=>Number.isFinite(n)&&Math.abs(n)<=10000);
const text=(s,n)=>typeof s==='string'&&s.length<=n;
const number=(n,min,max)=>Number.isFinite(n)&&n>=min&&n<=max;
export const actionTypes=['move','toggleVisibility','toggleLight','toggleAudio','score','respawn','finish','purchase'];
export function objectExtensions(o){const out={};if(o.particles!=null){const v=o.particles;if(!number(v.count,1,128)||!Number.isInteger(v.count)||!number(v.speed,0,5)||!number(v.range,1,20)||!/^#[0-9a-f]{6}$/i.test(v.color))throw Error('Invalid particle emitter.');out.particles={count:v.count,speed:v.speed,range:v.range,color:v.color};}for(const k of ['locked','hidden'])if(o[k]!=null){if(typeof o[k]!=='boolean')throw Error('Invalid '+k);out[k]=o[k];}if(o.tags!=null){if(!Array.isArray(o.tags)||o.tags.length>12||o.tags.some(t=>!text(t,32)))throw Error('Invalid object tags.');out.tags=[...o.tags];}if(o.animation!=null){const a=o.animation;if(!text(a.clip,100)||!number(a.speed,0,4)||typeof a.loop!=='boolean')throw Error('Invalid animation.');out.animation={clip:a.clip,speed:a.speed,loop:a.loop};}if(o.character!=null){const c=o.character;if(!number(c.speed,0,12)||!Array.isArray(c.waypoints)||c.waypoints.length>16||!c.waypoints.every(vec)||o.parentId||o.shape!=='box'||o.behavior!=='solid'||o.vehicle)throw Error('Characters require a root solid box and valid waypoints.');out.character={speed:c.speed,waypoints:c.waypoints.map(v=>[...v]),avatar:avatarProfile(c.avatar)};}return out;}
export function foundationSettings(p){const ids=new Set(p.objects.map(o=>o.id)),out={};if(p.rules!=null){if(!Array.isArray(p.rules)||p.rules.length>64)throw Error('Maximum 64 gameplay rules.');const unique=new Set();out.rules=p.rules.map(r=>{if(!text(r.id,100)||!r.id||unique.has(r.id)||!['interact','touch','timer'].includes(r.event)||!ids.has(r.source)||!number(r.cooldown,1,600)||typeof r.once!=='boolean'||!Array.isArray(r.actions)||r.actions.length<1||r.actions.length>8)throw Error('Invalid gameplay rule.');unique.add(r.id);return {id:r.id,event:r.event,source:r.source,cooldown:r.cooldown,once:r.once,actions:r.actions.map(a=>{if(!actionTypes.includes(a.type)||!ids.has(a.target)||!number(a.amount,-1000,1000)||!vec(a.offset))throw Error('Invalid rule action or target.');return {type:a.type,target:a.target,amount:a.amount,offset:[...a.offset]};})};});}
if(p.joints!=null){if(!Array.isArray(p.joints)||p.joints.length>32)throw Error('Maximum 32 physics links.');const unique=new Set();out.joints=p.joints.map(j=>{const a=p.objects.find(o=>o.id===j.a),b=p.objects.find(o=>o.id===j.b);if(!text(j.id,100)||unique.has(j.id)||!['distance','spring','hinge','lock'].includes(j.type)||!a||!b||a===b||a.behavior!=='solid'||b.behavior!=='solid'||a.shape==='group'||b.shape==='group'||!number(j.distance,.1,100)||!number(j.stiffness,1,1000))throw Error('Invalid physics link.');unique.add(j.id);return {id:j.id,type:j.type,a:j.a,b:j.b,distance:j.distance,stiffness:j.stiffness};});}
if(p.hud!=null){if(!Array.isArray(p.hud)||p.hud.length>20)throw Error('Maximum 20 HUD widgets.');const unique=new Set();out.hud=p.hud.map(w=>{if(!text(w.id,100)||unique.has(w.id)||!['label','score','health','inventory','button'].includes(w.type)||!text(w.text,160)||!number(w.x,0,95)||!number(w.y,0,95)||!number(w.width,5,80)||!/^#[0-9a-f]{6}$/i.test(w.color)||!text(w.target,100)||(w.type==='button'&&!ids.has(w.target)))throw Error('Invalid HUD widget.');unique.add(w.id);return {id:w.id,type:w.type,text:w.text,x:w.x,y:w.y,width:w.width,color:w.color,target:w.target};});}
if(p.platform!=null){const c=p.platform;if(!text(c.defaultLocale,12)||!Array.isArray(c.translations)||c.translations.length>100)throw Error('Invalid localisation settings.');out.platform={defaultLocale:c.defaultLocale,translations:c.translations.map(t=>{if(!text(t.key,160)||!text(t.locale,12)||!text(t.value,160))throw Error('Invalid translation.');return {key:t.key,locale:t.locale,value:t.value};})};}return out;}
export function projectWarnings(project){const warnings=[];if(!project.objects.some(o=>o.behavior==='solid'))warnings.push('Add a solid floor before playing.');if(project.objects.length>150)warnings.push('Large object count: test performance on a phone.');if(project.objects.some(o=>o.shape==='model'&&o.behavior==='solid'))warnings.push('Imported solid models currently use box collision.');for(const j of project.joints||[])if(!project.objects.some(o=>[j.a,j.b].includes(o.id)&&(o.physics?.dynamic||o.vehicle||o.character)))warnings.push('Physics link '+j.id+' connects two static objects.');return warnings;}
